<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Shared\Security\SecretDigester;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClient;

/**
 * Infrastructure adapter that implements ClientStoreGateway by reading TrustedClient entities
 * from the Access bounded context.
 *
 * This class translates between the Access domain's TrustedClient aggregate and the OAuth
 * domain's ClientData value object, acting as an anti-corruption layer that keeps the OAuth
 * application layer agnostic of persistence details. It handles all validation steps — client
 * existence, enabled status, public-access flag, secret verification, and redirect-URI matching
 * — logging a structured error message for each rejection reason without leaking details to
 * callers.
 *
 * Redirect-URI matching supports exact matches and a wildcard suffix ("*") restricted
 * to localhost origins for local development.
 *
 * Clients are resolved from the request tenant with TrustedClientFinder: the tenant's own client
 * or a global one, never a client of another tenant (task 022).
 */
class ClientStoreAdapter implements ClientStoreGateway
{
    use LoggerAwareTrait;

    /** Grants of a client without registered grant types. */
    public const array DEFAULT_GRANTS = ['authorization_code', 'refresh_token'];
    /** Response types of a client without registered response types. */
    private const array DEFAULT_RESPONSE_TYPES = ['code'];

    public function __construct(
        private readonly SecretDigester $digester,
        private readonly TrustedClientFinder $clients,
    ) {
    }

    /**
     * Looks up the client by ID and verifies, in constant time, the provided secret against the stored digest.
     * Returns null if the client is not found, disabled, or the secret is wrong.
     */
    #[Override]
    public function clientData(string $tenant, string $clientId, string $clientSecret): ?ClientData
    {
        $existent = $this->clients->findForTenantName($tenant, $clientId);
        if ($existent) {
            if (!$existent->isEnabled()) {
                // Not enabled
                $this->notEnabled($clientId);
                return null;
            } elseif (!$existent->verifySecretOauth($this->digester, $clientSecret)) {
                // Wrong passwrod
                $this->wrongPassword($clientId);
                return null;
            } else {
                return $this->mapClientData($existent);
            }
        } else {
            // No code
            $this->inexistent($clientId);
            return null;
        }
    }

    /**
     * Looks up the client by ID and returns its data if it exists and is enabled.
     * Returns null if the client is not found or is disabled.
     */
    #[Override]
    public function findEnabledClient(string $tenant, string $clientId): ?ClientData
    {
        $existent = $this->clients->findForTenantName($tenant, $clientId);
        if ($existent === null) {
            $this->inexistent($clientId);
            return null;
        }
        if (!$existent->isEnabled()) {
            $this->notEnabled($clientId);
            return null;
        }
        return $this->mapClientData($existent);
    }

    /**
     * Looks up the client and verifies it is both enabled and marked as publicly accessible.
     * Returns null if the client is not found, disabled, or does not allow public access.
     */
    #[Override]
    public function preValidatedClient(string $tenant, string $clientId): ?ClientData
    {
        $existent = $this->clients->findForTenantName($tenant, $clientId);
        if ($existent) {
            if (!$existent->isEnabled()) {
                $this->notEnabled($clientId);
                // Not enabled
                return null;
            } elseif (!$existent->isPublicAllow()) {
                // Not public allowed
                $this->notPublic($clientId);
                return null;
            } else {
                return $this->mapClientData($existent);
            }
        } else {
            $this->inexistent($clientId);
            return null;
        }
    }

    /**
     * Looks up the client and additionally verifies that the given redirect URL is registered
     * for it; supports exact matching, server-relative URLs, and localhost wildcard suffixes.
     * Returns null on any failure including an unregistered redirect URL.
     */
    #[Override]
    public function publicClientData(string $id, string $tenant, string $redirectUrl, string $scope): ?ClientData
    {
        $existent = $this->clients->findForTenantName($tenant, $id);
        if ($existent) {
            if (!$existent->isEnabled()) {
                $this->notEnabled($id);
                // Not enabled
                return null;
            } elseif (!$existent->isPublicAllow()) {
                // Not public allowed
                $this->notPublic($id);
                return null;
            } else {
                $allowed = false;
                $redirects = $existent->getAllowedRedirects() ?? [];
                foreach ($redirects as $redirect) {
                    if ($redirect === null) {
                        continue;
                    }
                    $url = $redirect->getUrl() ?? '';
                    if ($redirectUrl === $url || $this->matchesLocalhostWildcard($url, $redirectUrl)) {
                        $allowed = true;
                        break;
                    }
                }
                if (!$allowed) {
                    // No redirect existent
                    $this->notAllowed($id, $redirectUrl);
                    return null;
                } else {
                    return $this->mapClientData($existent);
                }
            }
        } else {
            $this->inexistent($id);
            return null;
        }
    }

    /**
     * Returns the URL of the first non-empty registered redirect URI for the client, or null if
     * the client does not exist, is disabled, or has no redirect URIs configured.
     */
    #[Override]
    public function defaultRedirectUri(string $tenant, string $clientId): ?string
    {
        $client = $this->clients->findForTenantName($tenant, $clientId);
        if ($client === null || !$client->isEnabled()) {
            return null;
        }
        $redirects = $client->getAllowedRedirects() ?? [];
        foreach ($redirects as $redirect) {
            $url = $redirect?->getUrl() ?? '';
            if ($url !== '') {
                return $url;
            }
        }
        return null;
    }

    /**
     * Exact match only, among the client's registered redirect URIs: no localhost wildcard.
     */
    #[Override]
    public function allowsPostLogoutRedirect(string $tenant, string $clientId, string $redirectUri): bool
    {
        $client = $this->clients->findForTenantName($tenant, $clientId);
        if ($client === null || !$client->isEnabled() || $redirectUri === '') {
            return false;
        }
        foreach ($client->getAllowedRedirects() ?? [] as $redirect) {
            if ($redirect?->getUrl() === $redirectUri) {
                return true;
            }
        }
        $this->notAllowed($clientId, $redirectUri);
        return false;
    }

    /**
     * Matches a registered "http://localhost[:port][/path]*" pattern against a redirect URI.
     * The redirect is parsed so that userinfo tricks ("http://localhost:4200@evil.com") or
     * look-alike hosts cannot satisfy a plain string prefix. An empty port in the pattern
     * ("http://localhost:*") accepts any port; the wildcard otherwise only extends the path.
     */
    private function matchesLocalhostWildcard(string $pattern, string $redirectUrl): bool
    {
        if (!str_ends_with($pattern, '*')
            || !preg_match('#^http://localhost(?::(\d*))?(/[^*]*)?$#', substr($pattern, 0, -1), $expected, PREG_UNMATCHED_AS_NULL)
        ) {
            return false;
        }
        $actual = parse_url($redirectUrl);
        if (!is_array($actual)
            || ($actual['scheme'] ?? null) !== 'http'
            || strtolower($actual['host'] ?? '') !== 'localhost'
            || isset($actual['user'])
            || isset($actual['pass'])
            || isset($actual['fragment'])
        ) {
            return false;
        }
        $expectedPort = $expected[1] ?? null;
        $actualPort = $actual['port'] ?? null;
        if ($expectedPort === null ? $actualPort !== null : ($expectedPort !== '' && (int) $expectedPort !== $actualPort)) {
            return false;
        }
        $actualPath = ($actual['path'] ?? '') . (isset($actual['query']) ? '?' . $actual['query'] : '');
        return str_starts_with($actualPath, $expected[2] ?? '');
    }

    private function mapClientData(TrustedClient $trustedClient): ClientData
    {
        $allowedAudiences = [];
        foreach ($trustedClient->getAllowedAudiences() ?? [] as $allowed) {
            $audience = $allowed?->getAudience() ?? '';
            if ($audience !== '') {
                $allowedAudiences[] = $audience;
            }
        }
        // The Access enum uses kebab-case values; the protocol names are RFC 7591 snake_case.
        $authMethod = str_replace('-', '_', $trustedClient->getTokenEndpointAuthMethod()->value);
        return new ClientData(
            id: $trustedClient->getCode() ?? '',
            // Without registered grants the safe default applies: never the password grant (task 024).
            grants: JsonStringList::decode($trustedClient->getGrantTypesJson()) ?? self::DEFAULT_GRANTS,
            secretLogin: true,
            allowedScopesM2m: $trustedClient->getAllowedScopesM2m() ?? [],
            m2mTokenTtlSeconds: $trustedClient->getM2mTokenTtlSeconds() ?? 3600,
            requestObjectSigningAlg: $trustedClient->getRequestObjectSigningAlg(),
            jwksUri: $trustedClient->getJwksUri(),
            jwksJson: $trustedClient->getJwksJson(),
            tokenEndpointAuthMethod: $authMethod,
            allowedAudiences: $allowedAudiences,
            tenant: $trustedClient->getTenant()?->uid(),
            responseTypes: JsonStringList::decode($trustedClient->getResponseTypesJson()) ?? self::DEFAULT_RESPONSE_TYPES,
            // A public client has no secret to protect its codes: PKCE is always mandatory for it.
            requirePkce: $trustedClient->isRequirePkce() || $authMethod === 'none',
            requirePar: $trustedClient->isRequirePushedAuthorizationRequests(),
            tokenEndpointAuthSigningAlg: $trustedClient->getTokenEndpointAuthSigningAlg(),
            allowAllScopes: $trustedClient->isAllowAllScopes() ?? false,
            isResourceServer: $trustedClient->isIsResourceServer(),
            backChannelLogoutSessionRequired: $trustedClient->isBackChannelLogoutSessionRequired() ?? false,
            frontChannelLogoutSessionRequired: $trustedClient->isFrontChannelLogoutSessionRequired() ?? false,
        );
    }

    private function notPublic(string $clientId): void
    {
        $this->logError('Try to get a public token from a not public Trusted Client', ['client-id' => $clientId]);
    }

    private function notEnabled(string $clientId): void
    {
        $this->logError('Try to get a token from a not enabled Trusted Client', ['client-id' => $clientId]);
    }

    private function inexistent(string $clientId): void
    {
        $this->logError('Try to get a token for a inexistent Trusted Client', ['client-id' => $clientId]);
    }

    private function wrongPassword(string $clientId): void
    {
        $this->logError('Try to get a token for a Trusted Client with wrong password', ['client-id' => $clientId]);
    }

    private function notAllowed(string $clientId, string $url): void
    {
        $this->logError('Try to get a token for from a public Trusted Client with wrong redirect url', ['client-id' => $clientId, 'redirect-url' => $url]);
    }
}
